param([string]$ComsolRoot='D:\Program Files\COMSOL\COMSOL61\Multiphysics',[string]$MatlabRoot='F:\Program Files\MATLAB\R2023b',[string]$OutputDir=(Join-Path $PSScriptRoot '..\data\generated\two_by_three_comsol61'),[int]$Port=20362)
$ErrorActionPreference='Stop'; $root=(Resolve-Path -LiteralPath $ComsolRoot).Path; $out=[IO.Path]::GetFullPath($OutputDir); $runtime=Join-Path $out 'matlab_runtime'; New-Item -ItemType Directory -Force -Path $out,$runtime,(Join-Path $out 'logs'),(Join-Path $runtime 'tmp'),(Join-Path $runtime 'recovery')|Out-Null
$server=Join-Path $root 'bin\win64\comsolmphserver.exe'; $args="-port $Port -silent -recoverydir `"$(Join-Path $runtime 'recovery')`" -tmpdir `"$(Join-Path $runtime 'tmp')`""; $proc=Start-Process $server -ArgumentList $args -RedirectStandardOutput (Join-Path $out 'logs\build_server_stdout.txt') -RedirectStandardError (Join-Path $out 'logs\build_server_stderr.txt') -PassThru -WindowStyle Hidden
try { $until=(Get-Date).AddSeconds(45); while((Get-Date)-lt $until -and -not (Test-NetConnection localhost -Port $Port -InformationLevel Quiet -WarningAction SilentlyContinue)){Start-Sleep -Milliseconds 500}; if(-not(Test-NetConnection localhost -Port $Port -InformationLevel Quiet -WarningAction SilentlyContinue)){throw 'COMSOL server did not start'}; $matlab=Join-Path ((Resolve-Path -LiteralPath $MatlabRoot).Path) 'bin\matlab.exe'; $sp=$PSScriptRoot.Replace('\','/'); $op=$out.Replace('\','/'); $mp=(Join-Path $root 'mli').Replace('\','/'); $expr="addpath('$sp'); try, build_two_by_three_comsol('$op','$mp',$Port); catch ME, disp(getReport(ME,'extended','hyperlinks','off')); exit(1); end;"; & $matlab -batch $expr 1> (Join-Path $out 'logs\build_matlab_stdout.txt') 2> (Join-Path $out 'logs\build_matlab_stderr.txt'); $code=$LASTEXITCODE; "exit_code=$code"|Set-Content (Join-Path $out 'logs\build_matlab_exit_code.txt'); if($code -ne 0){exit $code} } finally {if(-not $proc.HasExited){Stop-Process -Id $proc.Id -Force}}
